const raw = $('Trigger').item.json.payload;
const ctx = typeof raw === 'string' ? JSON.parse(raw) : raw;

const tenant = ctx.tenant;
const client = ctx.client;
const history = ctx.history || [];

// Buscar serviços do tenant
return [{ json: ctx }];

const ctx = $('Parsear input').item.json;
const services = $('Buscar serviços').item.json || [];
const tenant = ctx.tenant;
const client = ctx.client;
const history = ctx.history || [];

// Formatar serviços para o prompt
const servicesText = services.map(s => 
  `- ${s.name}: R$ ${Number(s.price).toFixed(2)} (${s.duration_minutes}min)`
).join('\n');

// Formatar horários de funcionamento
const days = { sun: 'Domingo', mon: 'Segunda', tue: 'Terça', wed: 'Quarta', thu: 'Quinta', fri: 'Sexta', sat: 'Sábado' };
const openingHours = tenant.opening_hours || {};
const hoursText = Object.entries(days)
  .map(([key, label]) => {
    const h = openingHours[key];
    if (!h || !h.open) return `${label}: Fechado`;
    return `${label}: ${h.start} às ${h.end}`;
  })
  .join('\n');

// Construir mensagens de histórico para OpenAI
const historyMessages = history.map(m => ({
  role: m.role === 'assistant' ? 'assistant' : 'user',
  content: m.content
}));

const systemPrompt = `Você é ${tenant.ai_name || 'Assistente'}, atendente virtual da ${tenant.name}.

PERSONALIDADE:
${tenant.ai_personality || 'Seja simpático, próximo e profissional.'}

${tenant.ai_custom_instructions ? 'INSTRUÇÕES ESPECIAIS:\n' + tenant.ai_custom_instructions + '\n' : ''}
REGRAS DE COMUNICAÇÃO:
- Mensagens CURTAS (máximo 3 linhas por resposta)
- Use emojis com moderação
- Chame o cliente pelo nome quando souber
- Nunca invente horários ou disponibilidade
- Se não souber responder, diga que vai verificar

SERVIÇOS DISPONÍVEIS:
${servicesText}

HORÁRIOS DE FUNCIONAMENTO:
${hoursText}

CLIENTE:
- Nome: ${client?.name || ctx.sender_name}
- Pontos de fidelidade: ${client?.loyalty_points || 0}

PARA AGENDAR:
Quando o cliente quiser agendar, responda APENAS com este JSON (sem texto adicional):
{"action": "schedule", "service_name": "NOME_DO_SERVICO", "preferred_date": "YYYY-MM-DD ou null", "preferred_time": "HH:MM ou null"}

Para qualquer outra resposta, responda normalmente em texto.`;

return [{
  json: {
    ...ctx,
    services,
    system_prompt: systemPrompt,
    history_messages: historyMessages
  }
}];

const ctx = $('Montar system prompt').item.json;
const aiResponse = $('OpenAI ChatGPT').item.json;
const responseText = aiResponse.choices?.[0]?.message?.content?.trim() || 'Desculpe, tive um problema. Pode repetir?';

// Verificar se a IA quer agendar (retornou JSON)
let action = null;
let actionData = null;
try {
  const parsed = JSON.parse(responseText);
  if (parsed.action === 'schedule') {
    action = 'schedule';
    actionData = parsed;
  }
} catch (e) {
  // Resposta normal em texto
}

return [{
  json: {
    ...ctx,
    ai_response: responseText,
    action,
    action_data: actionData
  }
}];

// Após agendamento, o tool retorna a mensagem de confirmação
const toolResult = $('→ Tool Agendamento').item.json;
const ctx = $('Parsear resposta da IA').item.json;

return [{
  json: {
    ...ctx,
    final_response: toolResult.confirmation_message || 'Agendamento realizado! ✅'
  }
}];
